size_t ceph_gluster_lustre_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void ceph_gluster_lustre_init(void) {
    g_online = true;
    kprintf("[FS/CLUSTER] Ceph RADOS CRUSH + Lustre Parallel OST/MDT + GlusterFS AFR (%lu rules)\n", (unsigned long)ceph_gluster_lustre_db_size());
}

bool ceph_gluster_lustre_selftest(void) {
    return g_online && ceph_gluster_lustre_db_size() >= 3400;
}
